// Generated by vibelang from src/settings/route.ts; the migrate flow writes it again with each batch.
const rootTabs = {
    general: true,
    appearance: true,
    notifications: true,
    shortcuts: true,
    projects: true,
    workspaces: true,
    providers: true,
    models: true,
    extensions: true,
    servers: true,
    experimental: true,
    about: true,
};
const projectTabs = {
    general: true,
    workspaces: true,
    extensions: true,
};
const subtabs = {
    mcps: true,
    plugins: true,
    skills: true,
    lsps: true,
};
export function parseSettingsView(search, transient, pluginTabs) {
    const params = new URLSearchParams(search);
    const tab = params.get("tab") ?? "general";
    const server = params.get("server") ?? undefined;
    const project = params.get("project");
    const subtab = params.get("subtab");
    const nested = subtab && isSubtab(subtab) && tab === "extensions" ? subtab : undefined;
    if (project && server && isProjectTab(tab))
        return { type: "project", server, project, tab, subtab: nested, ...transient };
    // Links to a server's own page, which the Servers page replaced, name a server without a tab.
    if (!project && server && !params.has("tab"))
        return { type: "root", tab: "servers", server, ...transient };
    // The desktop's Plugins page is now the Plugins tab of Extensions, so links to it and `layout.settings("plugins")`
    // land there.
    if (!project && tab === "plugins")
        return { type: "root", tab: "extensions", server, subtab: "plugins", ...transient };
    if (!project && isRootTab(tab))
        return { type: "root", tab, server, subtab: nested === "lsps" ? undefined : nested, ...transient };
    if (!project && pluginTabs && isPluginTab(tab, pluginTabs))
        return { type: "root", tab, server, subtab: undefined, ...transient };
    return { type: "root", tab: "general", ...transient };
}
export function settingsViewUrl(view) {
    const params = new URLSearchParams();
    if (view.server)
        params.set("server", view.server);
    if (view.type === "project")
        params.set("project", view.project);
    // A server without a tab names the Servers page, so a root view with a server always names its tab.
    if (view.tab !== "general" || (view.type === "root" && view.server))
        params.set("tab", view.tab);
    if (view.tab === "extensions" && view.subtab)
        params.set("subtab", view.subtab);
    const search = params.toString();
    return search ? `/settings?${search}` : "/settings";
}
/** Where a view must go when the server it names is gone, or a project's server is unavailable. */
export function settingsViewRedirect(input) {
    const view = input.view;
    if (!view.server || !input.loaded)
        return;
    const server = input.servers.find((item) => item.key === view.server);
    if (view.type === "root")
        return server ? undefined : { ...view, server: undefined };
    if (!server)
        return { type: "root", tab: "projects" };
    // A starting WSL or SSH server connects shortly; only an unavailable one leaves the project page.
    if (!server.connected && !server.starting)
        return { type: "root", tab: "projects", server: server.key };
}
export function isRootTab(value) {
    return Object.hasOwn(rootTabs, value);
}
/** Host tabs win over a plugin page with the same id. */
export function isPluginTab(value, tabs) {
    return !isRootTab(value) && tabs.has(value);
}
export function isProjectTab(value) {
    return Object.hasOwn(projectTabs, value);
}
function isSubtab(value) {
    return Object.hasOwn(subtabs, value);
}
